package negocio;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import org.junit.jupiter.api.Test;class InvitacionComunidadDominioTest{@Test void validaIdentidadObjetivoYMensaje(){InvitacionComunidad x=new InvitacionComunidad();x.setPerfilEmisorId(1);x.setPerfilDestinatarioId(2);x.setObjetivo(ObjetivoInvitacionComunidad.COMPLETAR_PARTIDO);x.setFechaInvitacion(LocalDateTime.now());x.setFechaExpiracion(LocalDateTime.now().plusDays(1));assertDoesNotThrow(x::validar);x.setPerfilDestinatarioId(1);assertThrows(IllegalArgumentException.class,x::validar);}}
